<template>
  <div class="app" :class="$i18n.locale">
    <div id="load">
      <div class="load_hoshi">
        <img draggable="false" src="@/assets/hoshi_w.svg" alt="" />
      </div>
    </div>

    <router-view @openSound="openSound" @openSettings="openSettings"/>
    <el-dialog :visible="showDialog" :show-close="false" :close-on-click-modal="false" :title="firstDiag? $t('message.before_playing') : $t('message.sound_settings')">
      <div>{{$t('message.enable_sound')}}</div>
      <span slot="footer" class="dialog-footer">
    <el-button @click="doDisableMusic()">{{$t('message.no')}}</el-button>
    <el-button type="primary" @click="doEnableMusic">{{$t('message.yes')}}</el-button>
  </span>
    </el-dialog>
    <license-agreement @openSound="openSound" ref="license"></license-agreement>
    <setting-panel @openSound="openSound" ref="settings"></setting-panel>
  </div>
</template>

<script>
import licenseAgreement from "@/components/licenseAgreement.vue";
import settingPanel from "@/components/settingPanel.vue";
export default {
  components: {
    licenseAgreement,
    settingPanel
  },
  name: "App",
  props: {},
  data() {
    return {
      showDialog: false,
      bgm: undefined,
      firstDiag: true
    };
  },
  methods: {
    openSound(info){
      this.firstDiag = info;
      this.showDialog = true;
    },
    openSettings(){
      this.$refs.settings.doOpen()
    },
    doDisableMusic(){
      this.bgm.pause();
      this.bgm.currentTime = 0;
      this.showDialog = false;
      if (this.firstDiag){
        this.makeLoadFade();
        setTimeout(() => {
          this.makeLoadDisappear();
        }, 800);
      }
    },
    doEnableMusic(){
      this.bgm.play().catch(error => {
        console.error("Failed to play music automatically:", error);
        alert("Failed to play music.");
      });
      this.bgm.loop = true;
      this.showDialog = false;
      if (this.firstDiag){
        this.makeLoadFade();
        setTimeout(() => {
          this.makeLoadDisappear();
        }, 800);
      }
    },
    makeLoadDisappear() {
      document.getElementById('load').style.display =  "none";
      // console.log($("#load").css("display"));
    },

    makeLoadFade() {
      document.getElementById('load').style.opacity = 0;
    },
  },
  created() {
    console.log(this.$t('message.hello'))
    if (this.$route.path != '/home'){
      this.$router.replace("/home");
    }
    this.bgm = new Audio("music/magic.ogg");
    let NoDisclaimer = localStorage.getItem('noDisclaimer');
    if (!NoDisclaimer){
      setTimeout(() => {this.$refs.license.doOpen()}, 0)
    }
    else{
      setTimeout(() => {this.openSound(true)}, 0)
    }


    // if (this.$route.path != '/'){
    //
    // }
  },
};
</script>
