<script>
export default {
  data(){
    return{
      show: false,
      osInfo: {},
      cachedLang: '',
      langModified: false
    }
  },
  methods: {
    handleClose() {
      this.show = false
    },
    doOpen(){
      this.show = true
    },
    doOpenSound(){
      this.$emit('openSound', false)
    },
    langChange(lang){
      // if (!lang){
      //   let locale = ''
      //   if (navigator.language.indexOf('zh') !== 0){
      //     locale = 'en'
      //   }
      //   else{
      //     locale = navigator.language.toLowerCase().replace('-', '_');
      //   }
      //   this.$i18n.locale = locale;
      // }else{
      //   this.$i18n.locale = lang
      // }

      localStorage.setItem('locale', lang);
      this.cachedLang = lang;
      this.langModified = true;
    },
    doRefresh(){
      location.reload()
    }
  },
  created() {
    this.cachedLang = localStorage.getItem('locale');
  }
}
</script>

<template>
  <el-dialog :visible="show" :beforeClose="handleClose" :title="$t('message.settings')">
    <div class="audio_settings">
      <span>{{$t('message.settings_sound')}}</span>
      <button @click="doOpenSound">{{$t('message.settings_sound_setup')}}</button>
    </div>
    <div class="lang_settings">
      <span>{{$t('message.setting_lang')}}</span>
      <div class="lang_panel">
        <div class="switch-item" @click="langChange('')" :class="!cachedLang? 'active' : ''">{{$t('message.setting_lang_auto')}}</div>
        <div class="switch-item" @click="langChange('zh_cn')" :class="cachedLang == 'zh_cn'? 'active' : ''">简体中文</div>
        <div class="switch-item" @click="langChange('zh_tw')" :class="cachedLang == 'zh_tw'? 'active' : ''">繁體中文</div>
        <div class="switch-item" @click="langChange('en')" :class="cachedLang == 'en'? 'active' : ''">English</div>
      </div>
    </div>
    <div class="restart_prompt" v-if="langModified">
      <p>{{$t('message.setting_lang_restart')}}</p>
      <button @click="doRefresh">{{$t('message.setting_lang_restart_btn')}}</button>
    </div>
  </el-dialog>
</template>

<style scoped lang="scss">
.audio_settings{
  display: flex;
  justify-content: space-between;
  margin-bottom: 8px;
  button{
    font-family: "Cherry Bomb One", sans-serif;
    background-color: #a1529b;
    height: 28px;
    padding: 0 8px;
    border-radius: 28px;
    border: none;
    color: white;
    box-shadow: 0 0 4px black;
    cursor: pointer;
    transition: 300ms;
    &:active{
      color: #8a0194;
    }
  }
}
.lang_panel{
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 12px 0 0;
  width: 100%;
  background-color: #4b004f;
  height: 48px;
  border-radius: 16px;
  padding: 4px;
  gap: 8px;

  .switch-item {
    text-align: center;
    flex-grow: 1;
    width: 100%;
    height: 40px;
    line-height: 40px;
    border-radius: 12px;
    transition: 300ms;
    cursor: pointer;
    font-size: 14px;
    &:hover {
      background: rgba(255, 255, 255, 0.1);
    }

    &.active {
      background-color: #FFF;
      color: #a1529b;
    }
  }

}
.restart_prompt{
  display: flex;
  align-items: center;
  gap: 4px;
  justify-content: center;
  margin-top: 12px;
  margin-bottom: -8px;
  button{
    font-family: "Cherry Bomb One", sans-serif;
    background-color: #a1529b;
    height: 28px;
    padding: 0 8px;
    border-radius: 28px;
    border: none;
    color: white;
    box-shadow: 0 0 4px black;
    cursor: pointer;
    transition: 300ms;
    &:active{
      color: #8a0194;
    }
  }
}
</style>
