import Vue from 'vue'
import VueI18n from 'vue-i18n'
import zh_cn from './zh-cn'
import zh_tw from './zh-tw'
import en from './en'
console.log(navigator.language)
let locale = ''
if (navigator.language.indexOf('zh') !== 0){
    locale = 'en'
}
else{
    locale = navigator.language.toLowerCase().replace('-', '_');
}
console.log(locale)
// 1. 注册插件
Vue.use(VueI18n)

// 2. 创建 i18n 实例
const i18n = new VueI18n({
    locale: localStorage.getItem('locale') || locale, // 默认语言
    fallbackLocale: 'en', // 回退语言
    messages: {
        zh_cn,
        zh_tw,
        en
    }
})
export default i18n
